CREATE OR REPLACE FUNCTION public.base_org_read() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT private.base_org_admin() THEN RAISE EXCEPTION 'Chỉ Super Admin được quản trị phân quyền toàn Base.';END IF;RETURN jsonb_build_object('revision',coalesce((SELECT revision FROM base_org_state WHERE id),0),'config',private.base_config(),'staff',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'name',full_name,'status',status) ORDER BY full_name),'[]') FROM profiles),'catalog',(SELECT coalesce(jsonb_agg(jsonb_build_object('key',key,'label',label,'module',module,'supported',private.base_supported(key)) ORDER BY module,key),'[]') FROM base_permission_catalog),'events',(SELECT coalesce(jsonb_agg(x),'[]') FROM (SELECT id,actor_id,action,before_revision,after_revision,impact,before_data,after_data,created_at FROM base_permission_events ORDER BY created_at DESC LIMIT 50)x));END $$;